    def test_brainpoolP384r1_sha3_384(
        self, name: str, pk: bytes, msg: bytes, sig: bytes, expected: bool
    ):
        decoder = SEC1Encoder()
        public_key = decoder.decode_public_key(pk, brainpoolP384r1)

        try:
            signature = DEREncoder.decode_signature(sig)
            result = verify(signature, msg, public_key, brainpoolP384r1, sha3_384)
            self.assertEqual(result, expected, name)
        except Exception:
            self.assertFalse(expected, name)
